import React, { useReducer, useEffect, useRef, useState, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
    FaArrowLeft, FaPlay, FaPause,
    FaStore, FaBolt, FaQuestionCircle, FaTimes,
    FaCoins, FaClock, FaPencilAlt, FaCheck, FaTrophy
} from 'react-icons/fa';

import './MarketMaker.css';
import { gameReducer, INITIAL_STATE } from './Engine/gameLogic';
import AdvancedChart from './Components/AdvancedChart';
import TradingTerminal from './Components/TradingTerminal';

const SEVERITY_CONFIG = {
    high: { color: '#ef4444', bg: 'rgba(239,68,68,0.1)', border: 'rgba(239,68,68,0.4)', label: 'BIG IMPACT' },
    medium: { color: '#f59e0b', bg: 'rgba(245,158,11,0.1)', border: 'rgba(245,158,11,0.4)', label: 'MODERATE' },
    low: { color: '#3b82f6', bg: 'rgba(59,130,246,0.1)', border: 'rgba(59,130,246,0.4)', label: 'SMALL' },
};

const GAME_DURATION = 8 * 60; // 8 minutes in seconds

export default function MarketMaker() {

    const [gameState, dispatch] = useReducer(gameReducer, INITIAL_STATE);
    const [showRules, setShowRules] = useState(false);
    const [floatingText, setFloatingText] = useState(null);
    const [timeLeft, setTimeLeft] = useState(GAME_DURATION);
    const [gameOver, setGameOver] = useState(false);
    const [shopName, setShopName] = useState('YOUR SHOP');
    const [editingName, setEditingName] = useState(false);
    const [nameInput, setNameInput] = useState('YOUR SHOP');

    const tickerInterval = useRef(null);
    const timerInterval = useRef(null);
    const prevLastTradeType = useRef(null);
    const nameInputRef = useRef(null);

    useEffect(() => {
        dispatch({ type: 'INIT_MARKET' });
    }, []);

    // Market tick every second
    useEffect(() => {
        if (gameState.isSimulationRunning && !gameOver) {
            tickerInterval.current = setInterval(() => {
                dispatch({ type: 'MARKET_TICK' });

                // News event ~6% chance per tick
                if (Math.random() < 0.06) {
                    dispatch({ type: 'TRIGGER_EVENT' });
                }

                // Rival shopkeeper acts ~12% chance per tick
                if (Math.random() < 0.12) {
                    dispatch({ type: 'RIVAL_TICK' });
                }

                // Market crash: ~0.8% per tick, but only if 60+ ticks since last crash
                if (
                    Math.random() < 0.008 &&
                    gameState.tickCount - gameState.lastCrashTick > 60
                ) {
                    dispatch({ type: 'MARKET_CRASH' });
                }

                // Black market: ~1.5% per tick to spawn (when not already up)
                if (!gameState.blackMarket.available && Math.random() < 0.015) {
                    dispatch({ type: 'SPAWN_BLACK_MARKET' });
                }

                // Expire black market if past its tick window
                if (
                    gameState.blackMarket.available &&
                    gameState.tickCount >= gameState.blackMarket.expiresAt
                ) {
                    dispatch({ type: 'EXPIRE_BLACK_MARKET' });
                }
            }, 1000);
        } else {
            clearInterval(tickerInterval.current);
        }
        return () => clearInterval(tickerInterval.current);
    }, [gameState.isSimulationRunning, gameOver, gameState.tickCount, gameState.lastCrashTick, gameState.blackMarket.available, gameState.blackMarket.expiresAt]);

    // Countdown timer — only ticks when shop is open
    useEffect(() => {
        if (gameState.isSimulationRunning && !gameOver) {
            timerInterval.current = setInterval(() => {
                setTimeLeft(prev => {
                    if (prev <= 1) {
                        clearInterval(timerInterval.current);
                        // Apply loan penalty if player didn't repay
                        if (gameState.loan.active && !gameState.loan.repaid) {
                            dispatch({ type: 'LOAN_PENALTY' });
                        }
                        dispatch({ type: 'TOGGLE_SIMULATION', payload: false });
                        setGameOver(true);
                        return 0;
                    }
                    return prev - 1;
                });
            }, 1000);
        } else {
            clearInterval(timerInterval.current);
        }
        return () => clearInterval(timerInterval.current);
    }, [gameState.isSimulationRunning, gameOver, gameState.loan.active, gameState.loan.repaid]);

    // Floating cash popup on trade
    useEffect(() => {
        if (
            gameState.lastTradeType &&
            gameState.lastTradeType !== prevLastTradeType.current &&
            gameState.lastTradeDelta !== 0
        ) {
            const delta = gameState.lastTradeDelta;
            setFloatingText({ value: delta, id: Date.now() });
            prevLastTradeType.current = gameState.lastTradeType;
            const t = setTimeout(() => setFloatingText(null), 1400);
            return () => clearTimeout(t);
        }
    }, [gameState.lastTradeType, gameState.lastTradeDelta]);

    const toggleSimulation = () => {
        if (gameOver) return;
        dispatch({ type: 'TOGGLE_SIMULATION', payload: !gameState.isSimulationRunning });
    };

    const handleRestartGame = () => {
        setTimeLeft(GAME_DURATION);
        setGameOver(false);
        dispatch({ type: 'INIT_MARKET' });
    };

    // Shop name easter egg
    const handleNameClick = () => {
        setNameInput(shopName);
        setEditingName(true);
        setTimeout(() => nameInputRef.current?.focus(), 50);
    };

    const handleNameSave = () => {
        const trimmed = nameInput.trim();
        if (trimmed.length > 0) setShopName(trimmed.toUpperCase());
        setEditingName(false);
    };

    const handleNameKeyDown = (e) => {
        if (e.key === 'Enter') handleNameSave();
        if (e.key === 'Escape') setEditingName(false);
    };

    // Timer display
    const mins = String(Math.floor(timeLeft / 60)).padStart(2, '0');
    const secs = String(timeLeft % 60).padStart(2, '0');
    const timerFraction = timeLeft / GAME_DURATION;
    const timerUrgent = timeLeft <= 60;

    const priceDelta = gameState.currentMarketPrice - gameState.dayStartPrice;
    const isPositive = priceDelta >= 0;
    const currentNews = gameState.newsTicker;
    const severityStyle = currentNews ? SEVERITY_CONFIG[currentNews.severity] || SEVERITY_CONFIG.low : SEVERITY_CONFIG.low;
    const qd = Math.max(0, gameState.market.maxDemand - gameState.market.demandSlope * gameState.currentMarketPrice);
    const qs = Math.max(0, gameState.market.minSupply + gameState.market.supplySlope * gameState.currentMarketPrice);
    const excessDemand = qd - qs;

    // Score calculation
    const startingWealth = INITIAL_STATE.cash;
    const finalWealth = gameState.portfolioValue;
    const profit = finalWealth - startingWealth;
    const grade = profit >= 5000 ? 'A+' : profit >= 2000 ? 'A' : profit >= 0 ? 'B' : 'C';

    return (
        <div className="mm-game-container">
            <div className="mm-bg-grid" />

            {/* Floating cash popup */}
            <AnimatePresence>
                {floatingText && (
                    <motion.div
                        key={floatingText.id}
                        className={`mm-float-delta ${floatingText.value > 0 ? 'positive' : 'negative'}`}
                        initial={{ opacity: 1, y: 0, scale: 1 }}
                        animate={{ opacity: 0, y: -80, scale: 1.3 }}
                        exit={{ opacity: 0 }}
                        transition={{ duration: 1.3, ease: 'easeOut' }}
                    >
                        {floatingText.value > 0 ? '+' : ''}₹{Math.abs(floatingText.value).toFixed(0)}
                        {floatingText.value > 0 ? ' 💰 SOLD!' : ' 📦 BOUGHT!'}
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Header */}
            <header className="mm-header">
                <Link to="/games" className="mm-back-btn">
                    <FaArrowLeft /> BACK
                </Link>

                <div className="mm-title-wrapper">
                    <FaStore className="mm-title-icon" />
                    <div>
                        {/* Easter egg: click to rename */}
                        {editingName ? (
                            <div className="mm-name-edit-row">
                                <input
                                    ref={nameInputRef}
                                    className="mm-name-input"
                                    value={nameInput}
                                    onChange={e => setNameInput(e.target.value)}
                                    onKeyDown={handleNameKeyDown}
                                    maxLength={24}
                                />
                                <button className="mm-name-save-btn" onClick={handleNameSave}><FaCheck /></button>
                            </div>
                        ) : (
                            <h1 className="mm-shop-name-btn" onClick={handleNameClick} title="Click to rename your shop">
                                {shopName.includes(' ') ? (
                                    <>
                                        {shopName.split(' ').slice(0, -1).join(' ')}{' '}
                                        <span className="mm-title-accent">{shopName.split(' ').slice(-1)}</span>
                                    </>
                                ) : (
                                    <span className="mm-title-accent">{shopName}</span>
                                )}
                                <FaPencilAlt className="mm-name-pencil" />
                            </h1>
                        )}
                        <span className="mm-title-sub">Supply & Demand Simulator</span>
                    </div>
                </div>

                <div className="mm-header-stats">
                    <button className="mm-rules-trigger" onClick={() => setShowRules(true)}>
                        <FaQuestionCircle /> HOW TO PLAY
                    </button>

                    {/* Timer */}
                    <div className={`mm-timer-display ${timerUrgent ? 'urgent' : ''}`}>
                        <FaClock />
                        <span className="mm-timer-digits">{mins}:{secs}</span>
                        <div className="mm-timer-bar">
                            <div className="mm-timer-fill" style={{ width: `${timerFraction * 100}%`, background: timerUrgent ? '#ef4444' : '#4cc9f0' }} />
                        </div>
                        {gameState.isSimulationRunning
                            ? <span className="live-badge pulse"><FaBolt /> OPEN</span>
                            : gameOver
                            ? <span className="live-badge ended">ENDED</span>
                            : <span className="live-badge paused">CLOSED</span>
                        }
                    </div>
                </div>
            </header>

            <main className="mm-main-grid">

                {/* LEFT COL */}
                <section className="mm-chart-section">

                    {/* Market Status */}
                    <div className="mm-market-status-row">
                        <div className="mm-market-price-box">
                            <span className="mm-box-label">Current Market Price</span>
                            <div className="mm-price-massive">
                                ₹{gameState.currentMarketPrice.toFixed(2)}
                                <span className={`mm-price-delta ${isPositive ? 'positive' : 'negative'}`}>
                                    {isPositive ? '▲' : '▼'} {isPositive ? '+' : ''}{priceDelta.toFixed(2)}
                                </span>
                            </div>
                            <span className="mm-price-hint">
                                Fair price (equilibrium): <strong>₹{gameState.market.currentEquilibriumPrice.toFixed(2)}</strong>
                            </span>
                        </div>

                        <div className="mm-engine-controls">
                            <button
                                className={`mm-btn-sim ${gameState.isSimulationRunning ? 'active' : ''}`}
                                onClick={toggleSimulation}
                                disabled={gameOver}
                            >
                                {gameState.isSimulationRunning
                                    ? <><FaPause /> CLOSE SHOP</>
                                    : <><FaPlay /> OPEN SHOP</>}
                            </button>
                        </div>
                    </div>

                    {/* Strategy Banner */}
                    <div className="mm-margin-banner positive">
                        <FaCoins /> Strategy: <strong>Buy</strong> when price is <strong>low</strong>, <strong>Sell</strong> when it is <strong>high</strong>. React to news events to stay ahead!
                    </div>

                    {/* Indicators */}
                    <div className="mm-indicators-row">
                        <div className="mm-indicator-card">
                            <span className="mm-indicator-label">Customer Demand</span>
                            <span className="mm-indicator-value demand-color">{qd.toFixed(0)} units</span>
                        </div>
                        <div className="mm-indicator-card">
                            <span className="mm-indicator-label">Supplier Supply</span>
                            <span className="mm-indicator-value supply-color">{qs.toFixed(0)} units</span>
                        </div>
                        <div className="mm-indicator-card">
                            <span className="mm-indicator-label">Fair Price</span>
                            <span className="mm-indicator-value eq-color">₹{gameState.market.currentEquilibriumPrice.toFixed(2)}</span>
                        </div>
                        <div className="mm-indicator-card">
                            <span className="mm-indicator-label">Market Mood</span>
                            <span className={`mm-indicator-value ${excessDemand > 0 ? 'demand-color' : 'supply-color'}`}>
                                {excessDemand > 0 ? '📈 High Demand' : '📉 Oversupply'}
                            </span>
                        </div>
                    </div>

                    {/* News Card */}
                    <AnimatePresence mode="wait">
                        {currentNews && (
                            <motion.div
                                className="mm-news-card"
                                key={currentNews.title + (currentNews.timestamp || '')}
                                style={{ borderLeftColor: severityStyle.color }}
                                initial={{ opacity: 0, y: -10 }}
                                animate={{ opacity: 1, y: 0 }}
                                exit={{ opacity: 0, y: 10 }}
                                transition={{ duration: 0.3 }}
                            >
                                <div className="mm-news-card-icon">{currentNews.icon}</div>
                                <div className="mm-news-card-body">
                                    <div className="mm-news-card-top">
                                        <span className="mm-news-card-category">{currentNews.category}</span>
                                        <span
                                            className="mm-news-card-severity"
                                            style={{ color: severityStyle.color, background: severityStyle.bg, borderColor: severityStyle.border }}
                                        >
                                            {severityStyle.label}
                                        </span>
                                    </div>
                                    <h4 className="mm-news-card-title">{currentNews.title}</h4>
                                    <p className="mm-news-card-desc">{currentNews.desc}</p>
                                    {currentNews.shopEffect && (
                                        <p className="mm-news-card-effect">{currentNews.shopEffect}</p>
                                    )}
                                </div>
                            </motion.div>
                        )}
                    </AnimatePresence>

                    {/* Chart */}
                    <div className="mm-chart-container">
                        <AdvancedChart
                            market={gameState.market}
                            currentMarketPrice={gameState.currentMarketPrice}
                            lastTradeTime={gameState.tradeHistory[0]?.time}
                        />
                    </div>
                </section>

                {/* RIGHT COL */}
                <aside className="mm-terminal-section">
                    <TradingTerminal state={gameState} dispatch={dispatch} gameOver={gameOver} />
                </aside>

            </main>

            {/* GAME OVER SCREEN */}
            <AnimatePresence>
                {gameOver && (
                    <motion.div
                        className="mm-modal-overlay"
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                    >
                        <motion.div
                            className="mm-gameover-modal"
                            initial={{ scale: 0.8, y: 40 }}
                            animate={{ scale: 1, y: 0 }}
                            transition={{ type: 'spring', stiffness: 180 }}
                        >
                            <div className="mm-go-scroll-area">
                                <div className="mm-go-icon"><FaTrophy /></div>
                                <h2 className="mm-go-title">TIME'S UP!</h2>
                                <p className="mm-go-shop">{shopName} has closed for the day.</p>

                                <div className="mm-go-stats">
                                    <div className="mm-go-stat">
                                        <span className="mm-go-stat-label">Starting Cash</span>
                                        <span className="mm-go-stat-value">₹{startingWealth.toLocaleString('en-IN')}</span>
                                    </div>
                                    <div className="mm-go-stat">
                                        <span className="mm-go-stat-label">Final Wealth</span>
                                        <span className="mm-go-stat-value highlight">₹{finalWealth.toLocaleString('en-IN', { maximumFractionDigits: 0 })}</span>
                                    </div>
                                    <div className="mm-go-stat">
                                        <span className="mm-go-stat-label">Net Profit / Loss</span>
                                        <span className={`mm-go-stat-value ${profit >= 0 ? 'green' : 'red'}`}>
                                            {profit >= 0 ? '+' : ''}₹{profit.toLocaleString('en-IN', { maximumFractionDigits: 0 })}
                                        </span>
                                    </div>
                                    <div className="mm-go-stat">
                                        <span className="mm-go-stat-label">Units Bought</span>
                                        <span className="mm-go-stat-value">{gameState.totalBought}</span>
                                    </div>
                                    <div className="mm-go-stat">
                                        <span className="mm-go-stat-label">Units Sold</span>
                                        <span className="mm-go-stat-value">{gameState.totalSold}</span>
                                    </div>
                                    <div className="mm-go-stat">
                                        <span className="mm-go-stat-label">Best Sell Streak</span>
                                        <span className="mm-go-stat-value" style={{ color: gameState.maxStreak >= 3 ? '#f59e0b' : undefined }}>
                                            {gameState.maxStreak >= 3 ? `🔥 ${gameState.maxStreak}x` : gameState.maxStreak > 0 ? `${gameState.maxStreak}x` : '—'}
                                        </span>
                                    </div>
                                    {gameState.loan.active && (
                                        <div className="mm-go-stat">
                                            <span className="mm-go-stat-label">Bank Loan</span>
                                            <span className={`mm-go-stat-value ${gameState.loan.repaid ? 'green' : 'red'}`}>
                                                {gameState.loan.repaid ? '✅ Repaid' : '⚠️ −₹6,500 penalty'}
                                            </span>
                                        </div>
                                    )}
                                    <div className="mm-go-grade">
                                        <span>Grade</span>
                                        <span className={`mm-go-grade-value grade-${grade.replace('+', 'plus')}`}>{grade}</span>
                                    </div>
                                </div>

                                <div className="mm-go-grade-guide">
                                    <span>A+: profit ≥ ₹5,000</span>
                                    <span>A: ≥ ₹2,000</span>
                                    <span>B: ≥ ₹0</span>
                                    <span>C: loss</span>
                                </div>
                            </div>

                            <div className="mm-go-actions mm-go-sticky-actions">
                                <button className="mm-modal-start-btn" onClick={handleRestartGame}>
                                    PLAY AGAIN
                                </button>
                                <Link to="/games" className="mm-go-back-link">← Back to Games</Link>
                            </div>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* HOW TO PLAY MODAL */}
            <AnimatePresence>
                {showRules && (
                    <motion.div
                        className="mm-modal-overlay"
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                    >
                        <motion.div
                            className="mm-rules-modal"
                            initial={{ scale: 0.9, y: 20 }}
                            animate={{ scale: 1, y: 0 }}
                        >
                            <button className="mm-modal-close" onClick={() => setShowRules(false)}>
                                <FaTimes />
                            </button>
                            <div className="mm-rules-scroll-area">
                                <h2><FaStore /> HOW YOUR SHOP WORKS</h2>
                                <div className="mm-rules-content">
                                    <section>
                                        <h4>🏪 Your Role</h4>
                                        <p>You own a shop. You buy goods from suppliers at a low price and sell them to customers at a higher price. Your profit is the difference!</p>
                                    </section>
                                    <section>
                                        <h4>⏱️ Time Limit</h4>
                                        <p>You have <strong>8 minutes</strong>. Press <strong>OPEN SHOP</strong> to start the timer. The market price will keep moving — buy and sell as many times as you can!</p>
                                    </section>
                                    <section>
                                        <h4>📦 How to Buy</h4>
                                        <p>Set a quantity, then press <strong>BUY FROM SUPPLIER</strong>. Your cash goes DOWN and your stock goes UP. The cost shown on the button is the exact amount you'll pay.</p>
                                    </section>
                                    <section>
                                        <h4>🛒 How to Sell</h4>
                                        <p>When price is higher than what you paid, press <strong>SELL TO CUSTOMERS</strong>. Your cash goes UP and your stock goes DOWN.</p>
                                    </section>
                                    <section>
                                        <h4>📊 The Chart</h4>
                                        <p>The <span style={{ color: '#ef4444' }}>red line</span> is customer demand — it slopes down (higher price = fewer buyers). The <span style={{ color: '#10b981' }}>green line</span> is supplier supply — it slopes up (higher price = more sellers). Where they cross is the <strong>fair equilibrium price</strong>. Hover over the chart to inspect demand &amp; supply at any price point!</p>
                                    </section>
                                    <section>
                                        <h4>📰 News Events</h4>
                                        <p>Events shift the curves — a festival raises demand, a factory shutdown reduces supply. Read each event and adjust your strategy!</p>
                                    </section>
                                    <section>
                                        <h4>💰 Bank Loan</h4>
                                        <p>Need more cash? Borrow <strong>₹5,000</strong> from the bank. But you must repay it before time runs out — or face a <strong>₹6,500 penalty</strong> (30% interest). Use it wisely to buy stock at the right moment!</p>
                                    </section>
                                    <section>
                                        <h4>🏪 Rival Shopkeeper</h4>
                                        <p>There's another shop in town! Watch for <strong>"Rival restocking"</strong> or <strong>"Rival undercutting"</strong> alerts. When the rival buys, prices nudge up. When they sell, prices dip. Use this as a signal!</p>
                                    </section>
                                    <section>
                                        <h4>🔥 Sell Streak</h4>
                                        <p>Sell when the price is <strong>above the equilibrium</strong> multiple times in a row to build a streak. At <strong>3+ streak</strong>, you earn a bonus multiplier on every sell — up to <strong>+50% revenue</strong>! Break the streak by selling below equilibrium.</p>
                                    </section>
                                    <section>
                                        <h4>🕵️ Black Market</h4>
                                        <p>Occasionally, a secret <strong>Black Market</strong> deal appears — buy stock at <strong>20% below market price</strong>. It only lasts <strong>5 seconds</strong>, so act fast! Then sell those units when the price rises for maximum profit.</p>
                                    </section>
                                    <section>
                                        <h4>📉 Market Crash</h4>
                                        <p>A sudden crash can drop the price by <strong>45%</strong> without warning. Don't panic-sell! The price will recover toward equilibrium. If you have cash ready, a crash is the best time to buy cheap stock.</p>
                                    </section>
                                    <section>
                                        <h4>🏆 Grading</h4>
                                        <p>A+: profit ≥ ₹5,000 &nbsp;|&nbsp; A: ≥ ₹2,000 &nbsp;|&nbsp; B: break-even &nbsp;|&nbsp; C: made a loss</p>
                                    </section>
                                </div>
                            </div>
                            <div className="mm-modal-sticky-cta">
                                <button className="mm-modal-start-btn" onClick={() => setShowRules(false)}>
                                    GOT IT — OPEN THE SHOP!
                                </button>
                            </div>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

// DayPanel.jsx — Handles Morning / Situation / Summary phases
import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { SITUATION_CARDS, FIXED_COST_PER_DAY, VARIABLE_COST_PER_CUP } from '../Engine/gameLogic';

const CUP_OPTIONS = [50, 100, 150];
const PRICE_OPTIONS = [12, 15, 20];

// ── Framer variants ────────────────────────────────────────────────────────────
const fadeSlide = {
  initial: { opacity: 0, y: 20 },
  animate: { opacity: 1, y: 0, transition: { duration: 0.3 } },
  exit:    { opacity: 0, y: -20, transition: { duration: 0.2 } },
};

// ── Morning Phase ──────────────────────────────────────────────────────────────
function MorningPhase({ state, dispatch }) {
  const { today, currentDay, cash } = state;
  const cups = today.cupsPlanned;
  const price = today.priceChosen;
  const vc = cups ? VARIABLE_COST_PER_CUP * cups : 0;
  const tc = FIXED_COST_PER_DAY + vc;
  const canOpen = cups !== null && price !== null;

  return (
    <motion.div key="morning" {...fadeSlide}>
      <div className="tt-morning-header">
        <span className="tt-day-badge">DAY {currentDay} / 7</span>
        <span className="tt-morning-title">☕ Morning Setup</span>
      </div>

      {/* Fixed Cost banner */}
      <div className="tt-fc-banner">
        <span className="tt-fc-label">FIXED COST (FC)</span>
        <span className="tt-fc-value">₹{FIXED_COST_PER_DAY}</span>
        <span className="tt-fc-note">
          ₹200 rent + ₹50 depreciation — <strong>paid no matter how many cups you sell!</strong>
        </span>
      </div>

      {/* Cups to prepare */}
      <div className="tt-section-label">How many cups to prepare?</div>
      <div className="tt-button-row">
        {CUP_OPTIONS.map(c => (
          <button
            key={c}
            className={`tt-option-btn ${cups === c ? 'selected' : ''}`}
            onClick={() => dispatch({ type: 'SET_CUPS', payload: c })}
          >
            {c} cups
          </button>
        ))}
      </div>

      {/* Variable Cost preview */}
      <div className="tt-vc-preview">
        <div>
          <div className="tt-vc-label">VARIABLE COST (VC)</div>
          <div className="tt-vc-formula">₹8 × {cups ?? '?'} cups</div>
        </div>
        <div className="tt-vc-value">₹{cups ? vc : '—'}</div>
      </div>

      {/* Price per cup */}
      <div className="tt-section-label">Price per cup?</div>
      <div className="tt-button-row">
        {PRICE_OPTIONS.map(p => (
          <button
            key={p}
            className={`tt-option-btn ${price === p ? 'selected' : ''}`}
            onClick={() => dispatch({ type: 'SET_PRICE', payload: p })}
          >
            ₹{p}
          </button>
        ))}
      </div>

      {/* TC preview */}
      <div className="tt-tc-preview">
        <span className="tt-tc-label">TOTAL COST (TC) = FC + VC</span>
        <span className="tt-tc-value">₹{canOpen ? tc : '—'}</span>
      </div>

      <button
        className="tt-open-btn"
        disabled={!canOpen}
        onClick={() => dispatch({ type: 'CONFIRM_MORNING' })}
      >
        🫖 Open the Tapri!
      </button>
    </motion.div>
  );
}

// ── Situation Phase ────────────────────────────────────────────────────────────
function SituationPhase({ state, dispatch }) {
  const { cardQueue, currentCardIndex, lastChoiceEffect } = state;
  const [chosenIndex, setChosenIndex] = useState(null);

  const cardId = cardQueue[currentCardIndex];
  const card = SITUATION_CARDS[cardId];
  if (!card) return null;

  const total = cardQueue.length;
  const current = currentCardIndex + 1;

  function handleChoice(idx) {
    if (chosenIndex !== null) return;
    setChosenIndex(idx);
    dispatch({ type: 'RESOLVE_CARD', payload: { cardId, choiceIndex: idx } });
  }

  function handleContinue() {
    setChosenIndex(null);
    dispatch({ type: 'ADVANCE_CARD' });
  }

  return (
    <motion.div key={`situation-${cardId}`} {...fadeSlide} className="tt-card-wrapper">
      <div className="tt-card-counter">Situation {current} of {total}</div>

      <div className="tt-situation-card">
        <div className="tt-card-character">
          <span className="tt-card-emoji">{card.emoji}</span>
          <span className="tt-card-character-name">{card.character}</span>
        </div>
        <div className="tt-card-title">{card.title}</div>
        <div className="tt-card-body">{card.body}</div>
      </div>

      <div className="tt-choices">
        {card.choices.map((choice, idx) => (
          <button
            key={idx}
            className={`tt-choice-btn ${chosenIndex === idx ? 'chosen' : ''}`}
            onClick={() => handleChoice(idx)}
            disabled={chosenIndex !== null}
          >
            {choice.label}
          </button>
        ))}
      </div>

      <AnimatePresence>
        {lastChoiceEffect && (
          <motion.div
            className="tt-effect-reveal"
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0 }}
          >
            <div className="tt-effect-text">💬 {lastChoiceEffect.flavorText}</div>
            <div className="tt-effect-delta">{effectSummary(lastChoiceEffect.effect)}</div>
          </motion.div>
        )}
      </AnimatePresence>

      {lastChoiceEffect && (
        <motion.button
          className="tt-continue-btn"
          onClick={handleContinue}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1, transition: { delay: 0.3 } }}
        >
          Continue →
        </motion.button>
      )}
    </motion.div>
  );
}

function effectSummary(eff) {
  if (!eff) return '';
  const parts = [];
  if (eff.cashDelta)        parts.push(`Cash: ₹${eff.cashDelta > 0 ? '+' : ''}${eff.cashDelta}`);
  if (eff.customersDelta)   parts.push(`Customers: ${eff.customersDelta > 0 ? '+' : ''}${eff.customersDelta}`);
  if (eff.fcModifier)       parts.push(`FC: +₹${eff.fcModifier} (one-time)`);
  if (eff.vcModifier)       parts.push(`VC: ${eff.vcModifier > 0 ? '+' : ''}₹${eff.vcModifier}`);
  if (eff.revenueModifier)  parts.push(`Revenue ×: ${eff.revenueModifier > 0 ? '+' : ''}${eff.revenueModifier.toFixed(2)}`);
  if (eff.priceOverride)    parts.push(`Price overridden to ₹${eff.priceOverride}`);
  return parts.join('  |  ') || 'No change';
}

// ── Summary Phase ──────────────────────────────────────────────────────────────
function SummaryPhase({ state, dispatch }) {
  const { today, currentDay, history } = state;
  // Get last history entry (just pushed by FINALIZE_DAY... but we call FINALIZE_DAY on "Next Day")
  // So during SUMMARY phase we compute preview from today's state
  const cups = today.cupsPlanned;
  const price = today.priceChosen;
  const customers = today.customersToday;
  const cupsSold = Math.min(cups, customers);
  const revenue = Math.round(price * cupsSold * (today.revenueModifier || 1.0));
  const fc = FIXED_COST_PER_DAY + (today.fcModifier || 0);
  const vc = (VARIABLE_COST_PER_CUP * cups) + (today.vcModifier || 0);
  const tc = fc + vc;
  const profit = revenue - tc;
  const maxBar = Math.max(fc, vc, tc, revenue, 1);

  const bars = [
    { label: 'Fixed Cost',    value: fc,      color: '#3B82F6', cls: 'fc' },
    { label: 'Variable Cost', value: vc,      color: '#F97316', cls: 'vc' },
    { label: 'Total Cost',    value: tc,      color: '#EF4444', cls: 'tc' },
    { label: 'Revenue',       value: revenue, color: '#22C55E', cls: 'rev' },
  ];

  const profitClass = profit > 0 ? 'positive' : profit < 0 ? 'negative' : 'neutral';

  return (
    <motion.div key="summary" {...fadeSlide}>
      <div className="tt-summary-header">
        <span className="tt-day-badge">DAY {currentDay} SUMMARY</span>
        <span className="tt-summary-title">📋 End of Day</span>
      </div>

      {/* Cost bars */}
      <div className="tt-cost-bars">
        {bars.map((bar, i) => (
          <motion.div
            className="tt-bar-row"
            key={bar.label}
            initial={{ opacity: 0, x: -10 }}
            animate={{ opacity: 1, x: 0, transition: { delay: i * 0.15 } }}
          >
            <span className="tt-bar-label" style={{ color: bar.color }}>
              <span className={`tt-concept-pill ${bar.cls}`}>{bar.label}</span>
            </span>
            <div className="tt-bar-track">
              <motion.div
                className="tt-bar-fill"
                style={{ background: bar.color }}
                initial={{ width: 0 }}
                animate={{ width: `${Math.round((bar.value / maxBar) * 100)}%`, transition: { delay: i * 0.15, duration: 0.5 } }}
              />
            </div>
            <span className="tt-bar-value" style={{ color: bar.color }}>₹{bar.value}</span>
          </motion.div>
        ))}
      </div>

      {/* Summary numbers */}
      <div style={{ display: 'flex', gap: '10px', marginBottom: '14px', flexWrap: 'wrap' }}>
        <div style={{ flex: 1, background: '#F9FAFB', borderRadius: '10px', padding: '10px 14px', border: '1px solid #E5E7EB', minWidth: '120px' }}>
          <div style={{ fontFamily: 'var(--tt-font-hand)', fontSize: '0.85rem', color: '#9CA3AF' }}>Cups Sold</div>
          <div style={{ fontFamily: 'var(--tt-font-mono)', fontWeight: 700, fontSize: '1.3rem', color: '#374151' }}>
            {cupsSold} / {cups}
          </div>
        </div>
        <div style={{ flex: 1, background: '#F9FAFB', borderRadius: '10px', padding: '10px 14px', border: '1px solid #E5E7EB', minWidth: '120px' }}>
          <div style={{ fontFamily: 'var(--tt-font-hand)', fontSize: '0.85rem', color: '#9CA3AF' }}>Customers</div>
          <div style={{ fontFamily: 'var(--tt-font-mono)', fontWeight: 700, fontSize: '1.3rem', color: '#374151' }}>
            {customers}
          </div>
        </div>
      </div>

      {/* Profit box */}
      <div className={`tt-profit-box ${profitClass}`}>
        <div className="tt-profit-label">Today's Profit = Revenue − TC</div>
        <div className={`tt-profit-value ${profitClass}`}>
          {profit >= 0 ? '+' : ''}₹{profit}
        </div>
      </div>

      {/* Flavor texts */}
      {today.flavorTexts && today.flavorTexts.length > 0 && (
        <div className="tt-flavor-chips">
          {today.flavorTexts.map((txt, i) => (
            <div key={i} className="tt-flavor-chip">"{txt}"</div>
          ))}
        </div>
      )}

      <button
        className="tt-next-btn"
        onClick={() => dispatch({ type: 'FINALIZE_DAY' })}
      >
        {state.currentDay >= state.maxDays ? '🏁 See Final Results!' : `Day ${currentDay + 1} →`}
      </button>
    </motion.div>
  );
}

// ── Root DayPanel ──────────────────────────────────────────────────────────────
export default function DayPanel({ state, dispatch }) {
  return (
    <div className="tt-day-panel">
      <AnimatePresence mode="wait">
        {state.phase === 'MORNING' && (
          <MorningPhase key="morning" state={state} dispatch={dispatch} />
        )}
        {state.phase === 'SITUATION' && (
          <SituationPhase key={`sit-${state.currentCardIndex}`} state={state} dispatch={dispatch} />
        )}
        {state.phase === 'SUMMARY' && (
          <SummaryPhase key="summary" state={state} dispatch={dispatch} />
        )}
      </AnimatePresence>
    </div>
  );
}

// TapriTycoon.jsx — Root component
// Teaches: Fixed Cost vs Variable Cost
import { useReducer, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { gameReducer, INITIAL_STATE } from './Engine/gameLogic';
import DayPanel from './Components/DayPanel';
import CostChart from './Components/CostChart';
import './TapriTycoon.css';

// ── Game Over: Star Rating + Reviewer Cards ─────────────────────────────────────
function starRating(totalProfit, cash) {
  if (cash < 0) return { stars: '⭐', tagline: 'This tapri closed. RIP. Sharma Uncle is devastated.' };
  if (totalProfit < 0) return { stars: '⭐⭐', tagline: 'Bhai went bankrupt. Chai was fine though.' };
  if (totalProfit < 500) return { stars: '⭐⭐⭐', tagline: 'Average. The stall is a little chaotic but okay.' };
  if (totalProfit < 2000) return { stars: '⭐⭐⭐⭐', tagline: 'Good chai, a bit expensive. Will come again.' };
  return { stars: '⭐⭐⭐⭐⭐', tagline: 'Best chai in the city! Bhai sahab is a business genius.' };
}

function reviewerCards(totalProfit) {
  const good = totalProfit >= 500;
  const great = totalProfit >= 2000;
  return [
    {
      emoji: '🧓', name: 'Sharma Uncle',
      stars: great ? '⭐⭐⭐⭐⭐' : good ? '⭐⭐⭐' : '⭐⭐',
      text: great
        ? '"Beta, teri chai se mujhe khushbu aati hai sapne mein. Aaj bhi free thi."'
        : good
        ? '"Theek thaak hai. Thodi aur meethi hoti toh perfect tha."'
        : '"Chai bekaar thi. Aur unhone free bhi nahi di. Shame shame."',
    },
    {
      emoji: '👩‍🎓', name: 'Dimple Didi',
      stars: great ? '⭐⭐⭐⭐⭐' : good ? '⭐⭐⭐⭐' : '⭐⭐',
      text: great
        ? '"My reel got 50K likes because of this tapri. Worth every rupee."'
        : good
        ? '"The aesthetic was okay but the cup was plain. No reel potential."'
        : '"Girl, even my sad reels don\'t look this depressing."',
    },
    {
      emoji: '👦', name: 'Chhotu',
      stars: '⭐⭐⭐⭐⭐',
      text: great
        ? '"Bhaiya ne aaj mujhe bonus diya! ₹10! Best day of my life!"'
        : '"Bhaiya thoda gusse mein rehte hain… lekin chai mast banate hain."',
    },
    {
      emoji: '👮', name: 'Inspector Sahib',
      stars: great ? '⭐⭐⭐' : '⭐⭐⭐⭐',
      text: great
        ? '"This stall is suspiciously profitable. I\'ll be back for another inspection."'
        : '"Very cooperative establishment. Processing fee was very reasonable."',
    },
    {
      emoji: '🏪', name: 'Raju Bhai',
      stars: good ? '⭐⭐⭐' : '⭐⭐⭐⭐',
      text: good
        ? '"Competitor tha, lekin respect hai. Good business sense."'
        : '"I tried to give him tips and he didn\'t listen. Bhai you had potential."',
    },
  ];
}

function GameOverOverlay({ state, dispatch }) {
  const { totalProfit, cash, history } = state;
  const { stars, tagline } = starRating(totalProfit, cash);
  const reviews = reviewerCards(totalProfit);

  const totalRevenue = history.reduce((s, h) => s + h.revenue, 0);
  const totalTC = history.reduce((s, h) => s + h.tc, 0);

  return (
    <motion.div
      className="tt-overlay"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
    >
      <motion.div
        className="tt-gameover-panel"
        initial={{ scale: 0.85, y: 40 }}
        animate={{ scale: 1, y: 0, transition: { type: 'spring', stiffness: 80, damping: 14 } }}
      >
        <div className="tt-gameover-title">🫖 Tapri Reviews Are In!</div>
        <div className="tt-gameover-stars">{stars}</div>
        <div className="tt-gameover-tagline">{tagline}</div>

        <div className="tt-gameover-stats">
          <div className="tt-gameover-stat">
            <div className="tt-gameover-stat-label">Total Profit</div>
            <div className={`tt-gameover-stat-value ${totalProfit >= 0 ? 'positive' : 'negative'}`}>
              {totalProfit >= 0 ? '+' : ''}₹{Math.round(totalProfit)}
            </div>
          </div>
          <div className="tt-gameover-stat">
            <div className="tt-gameover-stat-label">Final Cash</div>
            <div className={`tt-gameover-stat-value ${cash >= 0 ? 'positive' : 'negative'}`}>
              ₹{Math.round(cash)}
            </div>
          </div>
          <div className="tt-gameover-stat">
            <div className="tt-gameover-stat-label">Total Revenue</div>
            <div className="tt-gameover-stat-value positive">₹{totalRevenue}</div>
          </div>
          <div className="tt-gameover-stat">
            <div className="tt-gameover-stat-label">Total Cost</div>
            <div className="tt-gameover-stat-value negative">₹{totalTC}</div>
          </div>
        </div>

        {/* Key lesson */}
        <div style={{
          background: '#EFF6FF', border: '2px solid #3B82F6', borderRadius: '12px',
          padding: '14px 16px', marginBottom: '20px'
        }}>
          <div style={{ fontFamily: 'var(--tt-font-hand)', fontWeight: 700, color: '#1D4ED8', marginBottom: '6px', fontSize: '1.1rem' }}>
            📚 What you learned:
          </div>
          <div style={{ fontFamily: 'var(--tt-font-hand)', fontSize: '0.95rem', color: '#1E40AF', lineHeight: 1.5 }}>
            <strong>Fixed Cost (FC)</strong> = ₹250/day, no matter how much you sell.
            <br />
            <strong>Variable Cost (VC)</strong> = ₹8 × cups prepared — rises with output.
            <br />
            <strong>Total Cost (TC)</strong> = FC + VC. Profit only comes when Revenue &gt; TC!
          </div>
        </div>

        <div className="tt-reviews-title">Customer Reviews 📝</div>
        <div className="tt-reviews-list">
          {reviews.map((r, i) => (
            <motion.div
              key={r.name}
              className="tt-review-card"
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0, transition: { delay: i * 0.1 } }}
            >
              <div className="tt-review-reviewer">
                <span className="tt-review-emoji">{r.emoji}</span>
                <span className="tt-review-name">{r.name}</span>
                <span className="tt-review-stars">{r.stars}</span>
              </div>
              <div className="tt-review-text">{r.text}</div>
            </motion.div>
          ))}
        </div>

        <button
          className="tt-play-again-btn"
          onClick={() => dispatch({ type: 'INIT_GAME' })}
        >
          ☕ Run the Tapri Again!
        </button>
      </motion.div>
    </motion.div>
  );
}

// ── Rules Modal ─────────────────────────────────────────────────────────────────
function RulesModal({ onClose }) {
  return (
    <motion.div className="tt-rules-overlay" onClick={onClose}
      initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
      <motion.div className="tt-rules-panel" onClick={e => e.stopPropagation()}
        initial={{ scale: 0.9 }} animate={{ scale: 1 }}>
        <div className="tt-rules-title">☕ How to Play</div>
        <ul className="tt-rules-list">
          <li>🗓️ Run your tapri for <strong>7 days</strong></li>
          <li>📦 Each morning: choose cups to prepare + price per cup</li>
          <li>🔵 <strong>Fixed Cost (FC) = ₹250/day</strong> — paid regardless of sales</li>
          <li>🟠 <strong>Variable Cost (VC) = ₹8 × cups prepared</strong> — more cups = more cost</li>
          <li>🃏 Situation cards happen each day — your choices change costs & customers</li>
          <li>💰 Profit = Revenue − Total Cost. Keep cash positive!</li>
          <li>📈 Watch the cost graph build — FC stays flat, VC rises with output</li>
        </ul>
        <button className="tt-rules-close" onClick={onClose}>Got it, let's sell chai!</button>
      </motion.div>
    </motion.div>
  );
}

// ── Root Component ──────────────────────────────────────────────────────────────
export default function TapriTycoon() {
  const [state, dispatch] = useReducer(gameReducer, INITIAL_STATE);

  useEffect(() => {
    dispatch({ type: 'INIT_GAME' });
  }, []);

  const { phase, currentDay, maxDays, cash, history, showRules } = state;

  return (
    <div className="tt-game-container">
      {/* Graph paper background */}
      <div className="tt-bg-grid" />

      {/* Header */}
      <header className="tt-header">
        <div className="tt-header-title">
          <span>☕</span>
          Tapri Tycoon
        </div>

        <div className="tt-day-progress">
          {Array.from({ length: maxDays }, (_, i) => {
            const day = i + 1;
            let cls = '';
            if (day < currentDay || phase === 'GAME_OVER') cls = 'done';
            else if (day === currentDay) cls = 'current';
            return <div key={day} className={`tt-day-dot ${cls}`} title={`Day ${day}`} />;
          })}
        </div>

        <div className="tt-header-stats">
          <div className={`tt-stat-chip ${cash < 0 ? 'negative' : ''}`}>
            💰 ₹{Math.round(cash)}
          </div>
          <div className="tt-stat-chip">
            📅 Day {phase === 'GAME_OVER' ? maxDays : currentDay}/{maxDays}
          </div>
          <button className="tt-rules-btn" onClick={() => dispatch({ type: 'TOGGLE_RULES' })}>
            📖 Rules
          </button>
        </div>
      </header>

      {/* Main layout */}
      <div className="tt-main-layout">
        {/* Left: Day Panel */}
        <div>
          {phase !== 'GAME_OVER' && (
            <DayPanel state={state} dispatch={dispatch} />
          )}
          {phase === 'GAME_OVER' && (
            <div className="tt-day-panel" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#9CA3AF', fontFamily: 'var(--tt-font-hand)', fontSize: '1.2rem' }}>
              Game over! See results →
            </div>
          )}
        </div>

        {/* Right: Cost Chart */}
        <div className="tt-chart-panel">
          <div className="tt-chart-title">📊 Cost vs Revenue Chart</div>
          <div className="tt-chart-legend">
            <div className="tt-legend-item">
              <div className="tt-legend-dot" style={{ background: '#3B82F6' }} />
              <span>Fixed Cost</span>
            </div>
            <div className="tt-legend-item">
              <div className="tt-legend-dot" style={{ background: '#F97316' }} />
              <span>Variable Cost</span>
            </div>
            <div className="tt-legend-item">
              <div className="tt-legend-dot" style={{ background: '#EF4444' }} />
              <span>Total Cost</span>
            </div>
            <div className="tt-legend-item">
              <div className="tt-legend-dot" style={{ background: '#22C55E' }} />
              <span>Revenue</span>
            </div>
          </div>
          <div className="tt-chart-svg-wrapper">
            <CostChart history={history} currentDay={currentDay} />
          </div>
        </div>
      </div>

      {/* Overlays */}
      <AnimatePresence>
        {phase === 'GAME_OVER' && (
          <GameOverOverlay key="gameover" state={state} dispatch={dispatch} />
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showRules && (
          <RulesModal key="rules" onClose={() => dispatch({ type: 'TOGGLE_RULES' })} />
        )}
      </AnimatePresence>
    </div>
  );
}

