import React, { useState, useEffect } from 'react';
import { FaCalculator, FaTable, FaMagic } from 'react-icons/fa';
import { XBar } from './MeanPracticeData';
import './MeanComponents.css';

const ArithmeticMean = () => {
    const [seriesType, setSeriesType] = useState('individual'); // individual, discrete, continuous
    const [method, setMethod] = useState('direct'); // direct, shortcut, stepdev

    // State for inputs
    const [rawData, setRawData] = useState("10, 20, 30, 40, 50");
    const [discreteX, setDiscreteX] = useState("10, 20, 30, 40, 50");
    const [discreteF, setDiscreteF] = useState("2, 4, 10, 6, 3");
    const [assumedMean, setAssumedMean] = useState(30);
    const [commonFactor, setCommonFactor] = useState(10);

    const [result, setResult] = useState(null);

    // Calculation Logic
    useEffect(() => {
        calculateMean();
    }, [seriesType, method, rawData, discreteX, discreteF, assumedMean, commonFactor]);

    const calculateMean = () => {
        try {
            if (seriesType === 'individual') {
                const x = rawData.split(',').map(n => Number(n.trim())).filter(n => !isNaN(n));
                const N = x.length;
                if (N === 0) return;

                let mean = 0;
                let steps = [];

                if (method === 'direct') {
                    // Direct: ΣX / N
                    const sumX = x.reduce((a, b) => a + b, 0);
                    mean = sumX / N;
                    steps = [
                        `ΣX = ${sumX}`,
                        `N = ${N}`,
                        `Mean (<XBar />) = ${sumX} / ${N} = ${mean.toFixed(2)}`
                    ];
                } else {
                    // Shortcut: A + Σd/N
                    const d = x.map(val => val - assumedMean);
                    const sumD = d.reduce((a, b) => a + b, 0);
                    mean = assumedMean + (sumD / N);
                    steps = [
                        `Assumed Mean (A) = ${assumedMean}`,
                        `Deviations (d = X - A): [${d.join(', ')}]`,
                        `Σd = ${sumD}`,
                        `Mean (<XBar />) = ${assumedMean} + (${sumD} / ${N}) = ${mean.toFixed(2)}`
                    ];
                }
                setResult({ mean, steps });

            } else if (seriesType === 'discrete') {
                const x = discreteX.split(',').map(n => Number(n.trim()));
                const f = discreteF.split(',').map(n => Number(n.trim()));

                if (x.length !== f.length || x.length === 0) return setResult(null);

                const N = f.reduce((a, b) => a + b, 0);
                let mean = 0;
                let steps = [];

                if (method === 'direct') {
                    // ΣfX / Σf
                    const fx = x.map((val, i) => val * f[i]);
                    const sumFX = fx.reduce((a, b) => a + b, 0);
                    mean = sumFX / N;
                    steps = [
                        `Σf = ${N}`,
                        `ΣfX = ${sumFX}`,
                        `Mean (<XBar />) = ${sumFX} / ${N} = ${mean.toFixed(2)}`
                    ];
                } else if (method === 'shortcut') {
                    // A + Σfd/Σf
                    const d = x.map(val => val - assumedMean);
                    const fd = d.map((dev, i) => dev * f[i]);
                    const sumFD = fd.reduce((a, b) => a + b, 0);
                    mean = assumedMean + (sumFD / N);
                    steps = [
                        `A = ${assumedMean}`,
                        `Σfd = ${sumFD}`,
                        `Mean (<XBar />) = ${assumedMean} + (${sumFD} / ${N}) = ${mean.toFixed(2)}`
                    ];
                } else if (method === 'stepdev') {
                    // A + (Σfd'/Σf) * C
                    const d = x.map(val => val - assumedMean);
                    const dPrime = d.map(val => val / commonFactor);
                    const fdPrime = dPrime.map((dp, i) => dp * f[i]);
                    const sumFDPrime = fdPrime.reduce((a, b) => a + b, 0);
                    mean = assumedMean + (sumFDPrime / N) * commonFactor;
                    steps = [
                        `A = ${assumedMean}, C = ${commonFactor}`,
                        `d' = (X - A) / C`,
                        `Σfd' = ${sumFDPrime}`,
                        `Mean (<XBar />) = ${assumedMean} + (${sumFDPrime} / ${N}) × ${commonFactor} = ${mean.toFixed(2)}`
                    ];
                }
                setResult({ mean, steps });
            }
        } catch (e) {
            console.error("Calc Error", e);
        }
    };

    return (
        <div className="stats-section animate-fadeIn">
            <h2 className="stats-title">CALCULATING MEAN</h2>
            <p className="stats-subtitle">Interactive Mean Calculator</p>

            <div className="stats-grid-2">
                {/* Controls */}
                <div className="stats-card">
                    <h3 style={{ color: '#fff', marginBottom: '20px' }}>Configuration</h3>

                    {/* Series Selector */}
                    <div style={{ marginBottom: '20px' }}>
                        <label className="stats-label-text">Select Series Type:</label>
                        <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
                            {['individual', 'discrete'].map(type => (
                                <button
                                    key={type}
                                    className={`stats-btn ${seriesType === type ? 'stats-btn-primary' : 'stats-btn-outline'}`}
                                    onClick={() => setSeriesType(type)}
                                    style={{ textTransform: 'capitalize' }}
                                >
                                    {type} Series
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Method Selector */}
                    <div style={{ marginBottom: '20px' }}>
                        <label className="stats-label-text">Select Method:</label>
                        <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
                            <button
                                className={`stats-btn ${method === 'direct' ? 'stats-btn-primary' : 'stats-btn-outline'}`}
                                onClick={() => setMethod('direct')}
                            >
                                Direct
                            </button>
                            <button
                                className={`stats-btn ${method === 'shortcut' ? 'stats-btn-primary' : 'stats-btn-outline'}`}
                                onClick={() => setMethod('shortcut')}
                            >
                                Short-cut
                            </button>
                            {seriesType !== 'individual' && (
                                <button
                                    className={`stats-btn ${method === 'stepdev' ? 'stats-btn-primary' : 'stats-btn-outline'}`}
                                    onClick={() => setMethod('stepdev')}
                                >
                                    Step-Deviation
                                </button>
                            )}
                        </div>
                    </div>

                    {/* Data Inputs */}
                    <div style={{ background: 'rgba(0,0,0,0.2)', padding: '15px', borderRadius: '10px' }}>
                        {seriesType === 'individual' && (
                            <div>
                                <label className="stats-label-text">Data (Values separated by comma):</label>
                                <input
                                    type="text"
                                    value={rawData}
                                    onChange={(e) => setRawData(e.target.value)}
                                    className="stats-input"
                                    style={{ background: '#0f172a', color: '#fff', border: '1px solid #334155' }}
                                />
                            </div>
                        )}

                        {seriesType === 'discrete' && (
                            <>
                                <div style={{ marginBottom: '10px' }}>
                                    <label className="stats-label-text">x<sub>i</sub> (Values):</label>
                                    <input
                                        type="text"
                                        value={discreteX}
                                        onChange={(e) => setDiscreteX(e.target.value)}
                                        className="stats-input"
                                        style={{ background: '#0f172a', color: '#fff', border: '1px solid #334155' }}
                                    />
                                </div>
                                <div>
                                    <label className="stats-label-text">f<sub>i</sub> (Frequencies):</label>
                                    <input
                                        type="text"
                                        value={discreteF}
                                        onChange={(e) => setDiscreteF(e.target.value)}
                                        className="stats-input"
                                        style={{ background: '#0f172a', color: '#fff', border: '1px solid #334155' }}
                                    />
                                </div>
                            </>
                        )}

                        {/* Extra Params for Shortcut/StepDev */}
                        {method !== 'direct' && (
                            <div style={{ marginTop: '15px', display: 'flex', gap: '10px' }}>
                                <div style={{ flex: 1 }}>
                                    <label className="stats-label-text">Assumed Mean (A):</label>
                                    <input
                                        type="number"
                                        value={assumedMean}
                                        onChange={(e) => setAssumedMean(Number(e.target.value))}
                                        className="stats-input"
                                        style={{ background: '#0f172a', color: '#fff', border: '1px solid #334155' }}
                                    />
                                </div>
                                {method === 'stepdev' && (
                                    <div style={{ flex: 1 }}>
                                        <label className="stats-label-text">Common Factor (C):</label>
                                        <input
                                            type="number"
                                            value={commonFactor}
                                            onChange={(e) => setCommonFactor(Number(e.target.value))}
                                            className="stats-input"
                                            style={{ background: '#0f172a', color: '#fff', border: '1px solid #334155' }}
                                        />
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </div>

                {/* Output */}
                <div className="stats-card">
                    <h3 style={{ color: '#fff', marginBottom: '20px' }}>Calculation Steps</h3>
                    {result ? (
                        <div>
                            <div style={{ fontSize: '2.5rem', color: '#10b981', fontWeight: 'bold', marginBottom: '20px' }}>
                                <XBar /> = {result.mean.toFixed(2)}
                            </div>
                            <div style={{ display: 'grid', gap: '10px' }}>
                                {result.steps.map((step, i) => (
                                    <div key={i} className="calc-step-item">
                                        {/* Parse step string to replace XBar placeholder if exists, simple text replacement */}
                                        {step.split('<XBar />').map((part, idx, arr) => (
                                            <span key={idx}>
                                                {part}
                                                {idx < arr.length - 1 && <XBar />}
                                            </span>
                                        ))}
                                    </div>
                                ))}
                            </div>
                        </div>
                    ) : (
                        <p style={{ color: '#ef4444' }}>Invalid Data Input</p>
                    )}
                </div>
            </div>
        </div>
    );
};

export default ArithmeticMean;

import React, { useState } from 'react';
import { FaChevronDown, FaBookOpen, FaCalculator } from 'react-icons/fa';
import { motion, AnimatePresence } from 'framer-motion';
import { practiceData, XBar } from './MeanPracticeData';
import './MeanPractice.css';

// Notation Legend Component
const NotationLegend = () => (
    <div className="notation-legend">
        <h4 className="legend-title">Key Terms (NCERT Notation)</h4>
        <div className="legend-grid">
            <div className="legend-item">
                <span className="legend-symbol">x<sub>i</sub></span>
                <span className="legend-desc">Variable / Mid-value</span>
            </div>
            <div className="legend-item">
                <span className="legend-symbol">f<sub>i</sub></span>
                <span className="legend-desc">Frequency</span>
            </div>
            <div className="legend-item">
                <span className="legend-symbol"><XBar /></span>
                <span className="legend-desc">Arithmetic Mean</span>
            </div>
            <div className="legend-item">
                <span className="legend-symbol">N</span>
                <span className="legend-desc">Total Frequency (Σf<sub>i</sub>)</span>
            </div>
            <div className="legend-item">
                <span className="legend-symbol">d<sub>i</sub></span>
                <span className="legend-desc">Deviation (x<sub>i</sub> - A)</span>
            </div>
            <div className="legend-item">
                <span className="legend-symbol">u<sub>i</sub></span>
                <span className="legend-desc">Step Deviation</span>
            </div>
            <div className="legend-item">
                <span className="legend-symbol">A</span>
                <span className="legend-desc">Assumed Mean</span>
            </div>
        </div>
    </div>
);

// Reusable Solution Toggle Component
const SolutionToggle = ({ prob }) => {
    const [showSolution, setShowSolution] = useState(false);

    return (
        <div className="solution-section">
            <button
                onClick={() => setShowSolution(!showSolution)}
                className="solution-toggle-btn"
            >
                <div className="toggle-icon-wrap">
                    <FaCalculator size={14} />
                </div>
                <span>{showSolution ? 'Hide Solution' : 'Show Detailed Solution'}</span>
                <FaChevronDown
                    className={`transition-transform duration-300 ${showSolution ? 'rotate-180' : ''}`}
                    size={12}
                    style={{
                        transform: showSolution ? 'rotate(180deg)' : 'rotate(0deg)',
                        transition: 'transform 0.3s ease'
                    }}
                />
            </button>

            <AnimatePresence>
                {showSolution && (
                    <motion.div
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: 'auto' }}
                        exit={{ opacity: 0, height: 0 }}
                        transition={{ duration: 0.3, ease: 'easeInOut' }}
                        className="solution-wrapper"
                        style={{ overflow: 'hidden' }}
                    >
                        <div className="solution-details">
                            {prob.solTable && (
                                <div className="data-table-container">
                                    <div style={{ minWidth: 'max-content', padding: '10px' }}>
                                        {prob.solTable}
                                    </div>
                                </div>
                            )}

                            <div className="solution-card">
                                <h4 className="calc-header">
                                    <span style={{ display: 'inline-block', width: '8px', height: '8px', borderRadius: '50%', background: 'var(--neon-green)', marginRight: '8px' }}></span>
                                    Calculation Steps
                                </h4>
                                <div className="calc-content">
                                    {prob.calc}
                                </div>
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

const PracticeAccordion = ({ title, problems }) => {
    const [isOpen, setIsOpen] = useState(false);

    return (
        <div className="practice-accordion">
            <button
                onClick={() => setIsOpen(!isOpen)}
                className="accordion-trigger"
            >
                <div style={{ display: 'flex', alignItems: 'center' }}>
                    <div className="accordion-icon-box">
                        <FaBookOpen size={20} />
                    </div>
                    <span className="accordion-title">
                        {title}
                    </span>
                </div>
                <div className="accordion-chevron" style={{
                    transform: isOpen ? 'rotate(180deg)' : 'rotate(0deg)',
                    color: isOpen ? 'var(--neon-blue)' : 'inherit',
                    background: isOpen ? 'rgba(0, 153, 255, 0.1)' : 'rgba(255, 255, 255, 0.05)'
                }}>
                    <FaChevronDown />
                </div>
            </button>

            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: "auto", opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        transition={{ duration: 0.4, ease: [0.04, 0.62, 0.23, 0.98] }}
                        style={{ overflow: 'hidden' }}
                    >
                        <div className="accordion-content">
                            {problems.map((prob, idx) => (
                                <div key={idx} className="problem-container">
                                    <div className="problem-number">
                                        Q{idx + 1}
                                    </div>

                                    <div className="problem-body">
                                        <p className="question-text">
                                            {prob.q}
                                        </p>

                                        {prob.table && (
                                            <div className="data-table-container">
                                                <div style={{ minWidth: 'max-content' }}>
                                                    {prob.table}
                                                </div>
                                            </div>
                                        )}

                                        <SolutionToggle prob={prob} />
                                    </div>
                                </div>
                            ))}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

const MeanPractice = () => {
    return (
        <div className="mean-practice-container">
            <div className="practice-header">
                <h2 className="practice-title">
                    Solved Problems
                </h2>
            </div>

            <NotationLegend />

            <div className="accordions-wrapper">
                {practiceData.map((section) => (
                    <PracticeAccordion
                        key={section.id}
                        title={section.title}
                        problems={section.problems}
                    />
                ))}
            </div>

            <div className="pro-tip-box">
                <div className="pro-tip-glow"></div>
                <p style={{ position: 'relative', zIndex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '10px' }}>
                    <span style={{ fontSize: '1.5rem' }}>💡</span>
                    <span><strong>Pro Tip:</strong> Always check if the series is Inclusive or Exclusive before calculating.</span>
                </p>
            </div>
        </div>
    );
};

export default MeanPractice;

import React from 'react';

// Helper for Vertical Fractions
export const Fraction = ({ num, den }) => (
    <span style={{ display: 'inline-flex', flexDirection: 'column', alignItems: 'center', verticalAlign: 'middle', margin: '0 4px' }}>
        <span style={{ borderBottom: '1px solid currentColor', padding: '0 4px', display: 'block' }}>{num}</span>
        <span style={{ display: 'block', padding: '0 4px' }}>{den}</span>
    </span>
);

// Helper for X-Bar (Mean Symbol)
export const XBar = ({ sub }) => (
    <span style={{ display: 'inline-block' }}>
        <span style={{ textDecoration: 'overline' }}>X</span>
        {sub && <sub style={{ verticalAlign: 'sub', fontSize: '0.7em' }}>{sub}</sub>}
    </span>
